'use client'
/** Knob: the MATRIX card `ui-knob` (interactive: pointer and keyboard edit its data). Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { componentsBoard } from '@/lib/matrix/widgets/boards/components'

const preset = componentsBoard.find(p => p.id === 'ui-knob')!

export type MatrixKnobProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixKnob(props: MatrixKnobProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
